{
  "decisions": {
    "P0084R0F0001": {
      "action": "repair",
      "representative_fact_id": "P0082F0002",
      "corrections": [
        {
          "statement": "Forward에서는 무거운 커널 연산의 호출 횟수가 9개 줄었다",
          "limits": "p84:e647에 'forward에서는 무거운 커널 연산의 호출 횟수가 9개 줄어듦'이 명시됨. 세부 내역(method 0 bound 기준 레이어당 8→5회, lower/upper matmul 2→1, lower/upper bias matvec 2→1, matrix scaling + vector affine 2→1)은 p82:enh:e7에 존재함.",
          "kind": "method",
          "claim_status": "documented_method",
          "source_origin": "research_note",
          "conditions": [
            "Forward 방법",
            "무거운 커널 연산 호출 횟수 기준"
          ],
          "observations": [
            "원문 p84:e647: forward에서 무거운 커널 연산 호출 횟수 9개 감소",
            "원문 p82:enh:e7: method 0 bound 기준 레이어당 8→5회, 세부 커널별 감소 내역 존재"
          ],
          "parameters": [],
          "measurements": [],
          "element_ids": [
            "p84:e647",
            "p82:enh:e7"
          ]
        }
      ],
      "reason": "사실 진술('Forward에서는 무거운 커널 연산의 호출 횟수가 9개 줄었다')은 p84:e647에 그대로 기재되어 정확함. 그러나 limits에서 '레이어당 8→5회' 및 세부 커널별 감소 내역이 '원문에 없음'이라고 한 것은 p84:e647만 기준으로 할 때의 서술이며, 실제 해당 세부 내역은 p82:enh:e7에 모두 존재함. numeric_issues로 flagged된 수치 8, 5는 p82:enh:e7에서 확인되므로, limits를 수정하여 두 출처의 역할을 정확히 구분함."
    },
    "P0084R0F0002": {
      "action": "repair",
      "representative_fact_id": "P0082F0003",
      "corrections": [
        {
          "statement": "Backward에서는 forward 부분 12개(9+3), 실제 backward 부분에서는 3개 줄었다",
          "limits": "p84:e647에 'backward에서는 forward 부분 12개(9+3), 실제 backward 부분에서는 3개밖에 안줄어듦'이 명시됨. 세부 내역(split_pos_neg + bias accumulation 2→1, 레이어당 backward 단계 5→4회, method 1 기준 총 15회 감소)은 p82:enh:e7에 존재함.",
          "kind": "method",
          "claim_status": "documented_method",
          "source_origin": "research_note",
          "conditions": [
            "Backward 방법",
            "forward 쪽 relaxation/cache 통합 포함"
          ],
          "observations": [
            "원문 p84:e647: backward forward 부분 12개(9+3), 실제 backward 부분 3개 감소",
            "원문 p82:enh:e7: method 1 기준 split_pos_neg + bias accumulation 2→1, 레이어당 backward 단계 5→4회, 총 15회 감소"
          ],
          "parameters": [],
          "measurements": [],
          "element_ids": [
            "p84:e647",
            "p82:enh:e7"
          ]
        }
      ],
      "reason": "사실 진술('Backward에서는 forward 부분 12개(9+3), 실제 backward 부분에서는 3개 줄었다')은 p84:e647에 그대로 기재되어 정확함. 그러나 limits에서 'split_pos_neg + bias accumulation: 2→1', '레이어당 backward 단계 5→4회', '총 15회 감소'가 '원문에 없음'이라고 한 것은 p84:e647만 기준으로 할 때의 서술이며, 실제 해당 세부 내역은 p82:enh:e7에 모두 존재함. numeric_issues로 flagged된 수치 2, 1, 5, 4, 15는 p82:enh:e7에서 확인되므로, limits를 수정하여 두 출처의 역할을 정확히 구분함."
    }
  }
}
